package com.smartcanteen.web;
import com.smartcanteen.model.*; import com.smartcanteen.repo.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional; import javax.validation.Valid; import javax.validation.constraints.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api")
public class WalletController {
 private final OrderRepository orders; private final WalletTransactionRepository tx; private final AccountRepository accounts;
 public WalletController(OrderRepository o,WalletTransactionRepository t,AccountRepository a){orders=o;tx=t;accounts=a;}
 @GetMapping("/orders") public List<OrderSummary> history(Authentication a){List<OrderSummary> out=new ArrayList<>(); for(Order o:orders.findByAccountUsernameOrderByCreatedAtDesc(a.getName()))out.add(new OrderSummary(o)); return out;}
 @GetMapping("/wallet/transactions") public List<WalletTransaction> transactions(Authentication a){return tx.findByAccountUsernameOrderByCreatedAtDesc(a.getName());}
 @PostMapping("/wallet/top-up") @Transactional public AccountController.AccountResponse topUp(Authentication auth,@Valid @RequestBody AmountRequest r){if(r.amount.signum()<=0)throw new ApiException(400,"Amount must be positive");Account a=accounts.findByUsernameForUpdate(auth.getName()).orElseThrow(()->new ApiException(404,"Account not found"));a.credit(r.amount);tx.save(new WalletTransaction(a,null,r.amount,WalletTransaction.Type.CREDIT));return new AccountController.AccountResponse(a.getUsername(),a.getDisplayName(),a.getRole().name(),a.getWalletBalance());}
 @PostMapping("/orders/{id}/refund") @Transactional public AccountController.AccountResponse refund(Authentication auth,@PathVariable Long id){Order o=orders.findByIdForUpdate(id).orElseThrow(()->new ApiException(404,"Order not found"));boolean admin=auth.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));if(!admin&&!o.getAccountUsername().equals(auth.getName()))throw new ApiException(403,"Not authorized");if(o.isRefunded()||o.getPaymentMethod()!=PaymentMethod.WALLET)throw new ApiException(409,"Order cannot be refunded");Account a=accounts.findByUsernameForUpdate(o.getAccountUsername()).get();a.credit(o.getTotal());o.refund();orders.save(o);tx.save(new WalletTransaction(a,o,o.getTotal(),WalletTransaction.Type.CREDIT));return new AccountController.AccountResponse(a.getUsername(),a.getDisplayName(),a.getRole().name(),a.getWalletBalance());}
 public static class AmountRequest {@NotNull public BigDecimal amount;}
 public static class OrderSummary { public final Long orderId; public final java.math.BigDecimal total; public final String paymentMethod; public final java.time.Instant createdAt; public OrderSummary(Order o){orderId=o.getId();total=o.getTotal();paymentMethod=o.getPaymentMethod().name();createdAt=o.getCreatedAt();} }
}
